import {BufferGeometry,Color,DoubleSide,Float32BufferAttribute,Mesh,MeshPhongMaterial} from 'three';
import {gunzipSync} from 'three/addons/libs/fflate.module.js';
import {toByteArray} from 'base64-js';
import preview from './sortie-starter-aircraft.json' with {type:'json'};

// The bundled mesh is generated by tools/build-sortie-starter-preview.mjs from the Kestrel fighter package.
export function createSortieStarterAircraft(){
  const bytes=gunzipSync(toByteArray(preview.mesh));
  const data=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),color=new Color(),positions=[],normals=[],colors=[],indices=[];
  let offset=0;
  while(offset<data.byteLength){
    color.setRGB(bytes[offset]/255,bytes[offset+1]/255,bytes[offset+2]/255,'srgb');
    const vertices=data.getUint16(offset+3,true),elements=data.getUint16(offset+5,true);
    const base=positions.length/3;
    offset+=7;
    for(let i=0;i<vertices;i++){
      for(let axis=0;axis<3;axis++,offset+=2)positions.push(data.getInt16(offset,true)*preview.positionUnit);
      colors.push(color.r,color.g,color.b);
    }
    for(let i=0;i<vertices*3;i++,offset++)normals.push(data.getInt8(offset)/127);
    for(let i=0;i<elements;i++,offset+=2)indices.push(base+data.getUint16(offset,true));
  }
  const geometry=new BufferGeometry();
  geometry.setAttribute('position',new Float32BufferAttribute(positions,3));
  geometry.setAttribute('color',new Float32BufferAttribute(colors,3));
  geometry.setAttribute('normal',new Float32BufferAttribute(normals,3));
  geometry.setIndex(indices);
  const material=new MeshPhongMaterial({vertexColors:true,side:DoubleSide,specular:0x293c50,shininess:32});
  const model=new Mesh(geometry,material);model.name='kestrel sortie preview';
  return {model,undersideOffset:0,dispose(){geometry.dispose();material.dispose();}};
}
